import React, { useRef, useState } from "react";
import Webcam from "react-webcam";
import { useNavigate } from "react-router-dom";
import "./CSS/Register.css";
import { getAuth, createUserWithEmailAndPassword, updateProfile } from "firebase/auth";
import app from "../firebase/config.js";

function Register() {
  const webcamRef = useRef(null);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const handleRegister = async () => {
    const imageSrc = webcamRef.current.getScreenshot();
    if (!name || !email || !password || !imageSrc) {
      setError("All fields including face capture are required.");
      return;
    }

    try {
      const auth = getAuth(app);
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      await updateProfile(userCredential.user, { displayName: name });

      const response = await fetch("http://127.0.0.1:5000/register-face", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, image: imageSrc }),
      });

      const result = await response.json();
      if (result.success) {
        alert("Registered successfully!");
        navigate("/login");
      } else {
        setError("Face registration failed.");
      }
    } catch (err) {
      console.error(err);
      setError("Registration failed. Try again.");
    }
  };

  return (
    <div className="register-container">
      <h1 className="app-title">SecureMessage</h1>
      <div className="register-card">
        <h2>Register</h2>
        {error && <p className="error-text">{error}</p>}

        <label>Name</label>
        <input
          type="text"
          value={name}
          placeholder="Enter your name"
          onChange={(e) => setName(e.target.value)}
        />

        <label>Email</label>
        <input
          type="email"
          value={email}
          placeholder="Enter your email"
          onChange={(e) => setEmail(e.target.value)}
        />

        <label>Password</label>
        <input
          type="password"
          value={password}
          placeholder="Enter your password"
          onChange={(e) => setPassword(e.target.value)}
        />

        <div className="webcam-box">
          <Webcam
            ref={webcamRef}
            audio={false}
            height={160}
            screenshotFormat="image/jpeg"
            width={220}
          />
        </div>

        <button onClick={handleRegister}>Register</button>
        <p className="login-link" onClick={() => navigate("/login")}>
          Already Registered? Login
        </p>
      </div>
    </div>
  );
}

export default Register;
