import React, { useRef, useState } from "react";
import Webcam from "react-webcam";
import { useLocation, useNavigate } from "react-router-dom";
import "./CSS/FaceRecognition.css";

function FaceRecognition() {
  const webcamRef = useRef(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  const email = location.state?.email;

  const handleVerifyFace = async () => {
    setError("");
    setLoading(true);

    const imageSrc = webcamRef.current.getScreenshot();
    if (!imageSrc || !email) {
      setError("Face capture or email missing.");
      setLoading(false);
      return;
    }

    try {
      const response = await fetch("http://127.0.0.1:5000/verify-face", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, image: imageSrc }),
      });

      const result = await response.json();
      if (result.success) {
        navigate("/dashboard");
      } else {
        setError("Face verification failed.");
      }
    } catch (err) {
      console.error(err);
      setError("Error verifying face. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="face-container">
      <div className="face-box">
        <h2>Face Verification</h2>
        {error && <p className="error">{error}</p>}
        <Webcam
          ref={webcamRef}
          audio={false}
          height={240}
          screenshotFormat="image/jpeg"
          width={320}
          className="webcam"
        />
        <button onClick={handleVerifyFace} disabled={loading}>
          {loading ? "Verifying..." : "Verify Face"}
        </button>
      </div>
    </div>
  );
}

export default FaceRecognition;
